                    if st.lineHeightIsMinimum {
                        guard RichTextTheme.wordWindowsPages,
                              geometry(i).painter.computeLineMetrics().allSatisfy({ abs($0.height - _px(h)) < _px(0.01) }) else { return false }
                    }
